

-- Model: sat_bh1_timesheet_curr
-- Description: Current active record for TIMESHEET from SAT_BH1_TIMESHEET
-- Generated: 2025-05-19 21:48:09


WITH MAX_DATE AS (
    SELECT
        TIMESHEET_HKEY,
        MAX(DATELASTSYNC) AS MAX_TRANS_DATE
    FROM {{ source('eli_dv_rv', 'sat_bh1_timesheet') }}
    WHERE DELETE_FLAG = 'N'
    GROUP BY TIMESHEET_HKEY
)

SELECT
    SAT_SRC.TIMESHEET_HKEY,
    -- tagged: is_other_attr
    ADDEDATUTC,
    ADDEDBYUSERID,
    ADDITIONALBILLAMOUNT,
    ADDITIONALPAYAMOUNT,
    APPROVEDBY,
    APPROVEDDATE,
    APPROVINGCLIENTCONTACTID,
    BACKUPAPPROVINGCLIENTCONTACTID,
    BILLED,
    CALENDARINSTANCEID,
    DATEADDED,
    DATELASTMODIFIED,
    ENDDATE,
    EVALUATIONSTATEID,
    EXTERNALID,
    EXTERNALSOURCE,
    HOURSWORKED,
    ISDELETED,
    ISWORKFROMHOME,
    LASTMODIFIEDATUTC,
    LASTPROCESSEDON,
    LASTTIMESHEETVERSIONID,
    MODIFYINGUSERID,
    PAID,
    PROCESSINGSTATUSID,
    TIMEANDEXPENSEBRANCH,
    TIMELABOREVALSHEETSTATUSLOOKUPID,
    TIMESHEETENTRYAPPROVALSTATUSLOGID,
    UNITS,
    _AIRBYTE_EXTRACTED_AT,
    _AIRBYTE_GENERATION_ID,
    _AIRBYTE_RAW_ID
FROM {{ source('eli_dv_rv', 'sat_bh1_timesheet') }} SAT_SRC
INNER JOIN MAX_DATE MD
    ON SAT_SRC.TIMESHEET_HKEY = MD.TIMESHEET_HKEY
    AND SAT_SRC.DATELASTSYNC = MD.MAX_TRANS_DATE
    AND SAT_SRC.DELETE_FLAG = 'N'